// The engine worker: owns one CosmicCore WebAssembly instance and runs every request and the playback loop off the main
// thread. Each request is one bounded core call (at most 4096 macro steps), so pause, stop and new requests are handled
// between slices. Copyright (c) 2026 AiXenix.

import type { EngineOp, InitMessage, RequestMessage, WorkerToMain } from './protocol';
import type { EngineErrorCode, EngineSnapshot } from './types';

interface CosmicModule {
  _cxb_call(request: number): number;
  _cxb_binary_ptr(): number;
  _cxb_binary_len(): number;
  _cxb_input(size: number): number;
  _cxb_tracer_positions(): number;
  _cxb_tracer_groups(): number;
  _cxb_tracer_count(): number;
  _malloc(size: number): number;
  _free(ptr: number): void;
  UTF8ToString(ptr: number): string;
  stringToUTF8(text: string, ptr: number, maxBytes: number): void;
  lengthBytesUTF8(text: string): number;
  HEAPU8: Uint8Array;
  HEAPF64: Float64Array;
  HEAPU32: Uint32Array;
}

type ModuleFactory = (options: { locateFile: (path: string) => string }) => Promise<CosmicModule>;

interface WorkerScope {
  postMessage(message: WorkerToMain, transfer?: Transferable[]): void;
  onmessage: ((event: MessageEvent<InitMessage | RequestMessage>) => void) | null;
}

const scope = self as unknown as WorkerScope;

let core: CosmicModule | null = null;
let ready: Promise<CosmicModule> | null = null;
let playing = false;
let rate = 0;
let playTimer: ReturnType<typeof setTimeout> | null = null;
let lastSlice = 0;
/** Playback: simulation seconds owed to real time and not yet stepped (whole base steps are taken as it accumulates). */
let debt = 0;
/** The live world's base step, from the latest snapshot. */
let baseStep = 0;
/** At most this much real time is caught up after a stall (the rest is dropped, never stepped in a burst). */
const MAX_CATCH_UP_SECONDS = 1;

class CallError extends Error {
  readonly code: EngineErrorCode;
  constructor(code: EngineErrorCode, message: string) {
    super(message);
    this.code = code;
  }
}

/** One bridge call: JSON in, JSON out. Throws CallError for a refused request. */
function call(op: string, args: Record<string, unknown> = {}): Record<string, unknown> {
  if (!core) throw new CallError('engine_unavailable', 'the engine is not loaded');
  // JSON has no NaN or Infinity (stringify would turn them into null, which the bridge would read as "absent"): refuse here.
  const text = JSON.stringify({ ...args, op }, (key: string, value: unknown) => {
    if (typeof value === 'number' && !Number.isFinite(value)) {
      throw new CallError('invalid_argument', `${key || 'value'} must be a finite number (got ${String(value)})`);
    }
    return value;
  });
  const size = core.lengthBytesUTF8(text) + 1;
  const ptr = core._malloc(size);
  if (!ptr) throw new CallError('engine_unavailable', 'out of memory');
  let response: string;
  try {
    core.stringToUTF8(text, ptr, size);
    response = core.UTF8ToString(core._cxb_call(ptr));
  } finally {
    core._free(ptr);
  }
  const parsed = JSON.parse(response) as Record<string, unknown>;
  if (parsed.ok !== true) {
    throw new CallError((parsed.code as EngineErrorCode) ?? 'protocol', String(parsed.message ?? 'refused'));
  }
  return parsed;
}

/** The bridge's snapshot JSON plus the tracer arrays (copied out of the WASM heap) and the worker's playback state. */
function toSnapshot(raw: unknown): EngineSnapshot {
  if (!core) throw new CallError('engine_unavailable', 'the engine is not loaded');
  const json = raw as Record<string, unknown>;
  const count = core._cxb_tracer_count();
  const positions = new Float64Array(count * 3);
  const groups = new Uint32Array(count);
  if (count > 0) {
    positions.set(core.HEAPF64.subarray(core._cxb_tracer_positions() / 8, core._cxb_tracer_positions() / 8 + count * 3));
    groups.set(core.HEAPU32.subarray(core._cxb_tracer_groups() / 4, core._cxb_tracer_groups() / 4 + count));
  }
  delete json.tracerCount;
  if (typeof json.baseStep === 'number') baseStep = json.baseStep;
  return {
    ...(json as unknown as Omit<EngineSnapshot, 'tracers' | 'playing' | 'rate'>),
    tracers: { count, groups, positions },
    playing,
    rate,
  } as EngineSnapshot;
}

function transferOf(snapshot: EngineSnapshot | undefined): Transferable[] {
  if (!snapshot) return [];
  return [snapshot.tracers.positions.buffer as ArrayBuffer, snapshot.tracers.groups.buffer as ArrayBuffer];
}

function stopPlayback(): void {
  playing = false;
  debt = 0;
  if (playTimer !== null) {
    clearTimeout(playTimer);
    playTimer = null;
  }
}

/** One playback slice: advances rate × elapsed real time (bounded by 4096 macro steps), posts the snapshot. */
function playbackSlice(): void {
  playTimer = null;
  if (!playing || !core) return;
  const now = performance.now();
  const elapsed = Math.max(now - lastSlice, 0) / 1000;
  lastSlice = now;
  try {
    // Accumulate the owed simulation time; step only whole base steps of it and keep the remainder for the next slice.
    debt = Math.min(debt + rate * elapsed, rate * MAX_CATCH_UP_SECONDS + baseStep);
    if (!(baseStep > 0) || debt < baseStep) {
      playTimer = setTimeout(playbackSlice, 33);
      return;
    }
    const snapshot = toSnapshot(call('step', { seconds: debt, maxSteps: 4096 }).snapshot);
    const achieved = snapshot.lastStep?.achievedSeconds ?? 0;
    debt = Math.max(debt - achieved, 0);
    if (snapshot.lastStep?.limit === 'budget' || snapshot.lastStep?.limit === 'close_encounter') {
      // The core could not keep up within one bounded slice: drop the backlog beyond the catch-up bound.
      debt = Math.min(debt, rate * MAX_CATCH_UP_SECONDS);
    }
    if (snapshot.run !== 'running') {
      // A guard, speed limit, fault or pause stopped the world: playback stops with it.
      stopPlayback();
      snapshot.playing = false;
    }
    scope.postMessage({ type: 'snapshot', snapshot }, transferOf(snapshot));
  } catch (error) {
    stopPlayback();
    const code = error instanceof CallError ? error.code : 'engine_unavailable';
    // The world stopped stepping (for example a guard pause): report the current state.
    try {
      const snapshot = toSnapshot(call('snapshot').snapshot);
      scope.postMessage({ type: 'snapshot', snapshot }, transferOf(snapshot));
    } catch {
      scope.postMessage({ type: 'fatal', code, message: String((error as Error).message) });
    }
    return;
  }
  playTimer = setTimeout(playbackSlice, 33);
}

const DEBT_RESETTING_OPS: ReadonlySet<EngineOp> = new Set<EngineOp>(['loadScene', 'reset', 'loadSave', 'switchBranch', 'undo', 'redo', 'step', 'stepExact', 'setBaseStep']);

function handle(message: RequestMessage): WorkerToMain {
  const { id, op, args } = message;
  const opName: EngineOp = op;
  if (DEBT_RESETTING_OPS.has(opName)) {
    debt = 0;
    lastSlice = performance.now();
  }
  switch (opName) {
    case 'info':
      return { type: 'response', id, ok: true, result: call('info') };
    case 'play': {
      const r = Number(args.rate);
      if (!Number.isFinite(r) || r <= 0) throw new CallError('invalid_argument', 'play needs a finite rate > 0');
      const resumed = call('resume');
      rate = r;
      playing = true;
      debt = 0;
      lastSlice = performance.now();
      if (playTimer === null) playTimer = setTimeout(playbackSlice, 0);
      const snapshot = toSnapshot(resumed.snapshot);
      return { type: 'response', id, ok: true, result: null, snapshot };
    }
    case 'stop': {
      stopPlayback();
      const snapshot = toSnapshot(call('pause').snapshot);
      return { type: 'response', id, ok: true, result: null, snapshot };
    }
    case 'pause': {
      stopPlayback();
      const snapshot = toSnapshot(call('pause').snapshot);
      return { type: 'response', id, ok: true, result: null, snapshot };
    }
    case 'save': {
      call('save');
      const c = core as CosmicModule;
      const n = c._cxb_binary_len();
      const bytes = c.HEAPU8.slice(c._cxb_binary_ptr(), c._cxb_binary_ptr() + n);
      return { type: 'response', id, ok: true, result: null, bytes };
    }
    case 'loadSave': {
      const bytes = message.bytes;
      if (!(bytes instanceof Uint8Array) || bytes.length === 0) throw new CallError('invalid_argument', 'loadSave needs bytes');
      stopPlayback();
      const c = core as CosmicModule;
      const dst = c._cxb_input(bytes.length);
      c.HEAPU8.set(bytes, dst);
      const snapshot = toSnapshot(call('loadSave').snapshot);
      return { type: 'response', id, ok: true, result: null, snapshot };
    }
    case 'loadScene':
    case 'reset':
    case 'switchBranch': {
      stopPlayback();
      const r = call(op, args);
      const snapshot = toSnapshot(r.snapshot);
      return { type: 'response', id, ok: true, result: r.result ?? null, snapshot };
    }
    default: {
      const r = call(op, args);
      const snapshot = r.snapshot !== undefined ? toSnapshot(r.snapshot) : undefined;
      const result = op === 'addBodies' ? { createdIds: r.createdIds } : op === 'addObserver' ? { observerId: r.observerId } : null;
      if (snapshot && playing && snapshot.run !== 'running') {
        stopPlayback();
        snapshot.playing = false;
      }
      return { type: 'response', id, ok: true, result, snapshot };
    }
  }
}

async function load(engineUrl: string): Promise<CosmicModule> {
  const base = engineUrl.endsWith('/') ? engineUrl : `${engineUrl}/`;
  const module = (await import(/* @vite-ignore */ `${base}cosmic-core.mjs`)) as { default: ModuleFactory };
  return module.default({ locateFile: (path: string) => `${base}${path}` });
}

scope.onmessage = (event: MessageEvent<InitMessage | RequestMessage>) => {
  const message = event.data;
  if (message.type === 'init') {
    ready = load(message.engineUrl);
    ready.then(
      (module) => {
        core = module;
        scope.postMessage({ type: 'ready', info: call('info') });
      },
      (error: unknown) => {
        scope.postMessage({ type: 'fatal', code: 'engine_unavailable', message: `the WebAssembly core failed to load: ${String(error)}` });
      },
    );
    return;
  }
  if (message.type !== 'request') return;
  const respond = () => {
    try {
      const reply = handle(message);
      const transfer: Transferable[] = [];
      if (reply.type === 'response' && reply.ok) {
        transfer.push(...transferOf(reply.snapshot));
        if (reply.bytes) transfer.push(reply.bytes.buffer as ArrayBuffer);
      }
      scope.postMessage(reply, transfer);
    } catch (error) {
      const code: EngineErrorCode = error instanceof CallError ? error.code : 'protocol';
      scope.postMessage({ type: 'response', id: message.id, ok: false, code, message: String((error as Error).message) });
    }
  };
  if (core) {
    respond();
  } else if (ready) {
    ready.then(respond, () => {
      scope.postMessage({ type: 'response', id: message.id, ok: false, code: 'engine_unavailable', message: 'the WebAssembly core failed to load' });
    });
  } else {
    scope.postMessage({ type: 'response', id: message.id, ok: false, code: 'engine_unavailable', message: 'the engine was not initialised' });
  }
};
